mapper.select:
SELECT c.id, c.name, c.contract_no, c.pdf_url, c.member_phone, c.elder_id, c.elder_name, c.member_name, c.start_time, c.end_time, c.status, c.sort, c.level_desc, c.create_time, c.create_by, c.update_time, c.update_by, c.remark, c.check_in_no, c.sign_date, c.release_submitter, c.release_date, c.release_pdf_url, e.image AS elder_image FROM `contract` c LEFT JOIN `elder` e ON c.elder_id = e.id
AND c.contract_no LIKE CONCAT('%', #{contractNo}, '%')
AND c.elder_name LIKE CONCAT('%', #{elderName}, '%')
AND c.status = #{status}
AND c.start_time >= #{startTime}
AND c.end_time <= #{endTime}
ORDER BY c.create_time DESC
